import json,datetime
from pathlib import Path
p=Path('editorial15/calendar_q4.json');rows=json.loads(p.read_text())
def add(date,code,title,year,summary,url,ref,source):
 rows.append(dict(date=date,code=code,title=title,year=year,summary=summary,url=url,source_title=source,evidence='Date et événement explicitement attestés : '+ref,confidence='high'))
add('12-05','ZAF','La mort de Nelson Mandela',2013,'Nelson Mandela meurt le 5 décembre 2013 à Johannesburg. Son parcours relie la lutte contre l’apartheid, l’emprisonnement et la transition démocratique sud-africaine.','https://www.nelsonmandela.org/biography','turn272search1','Nelson Mandela Foundation')
add('12-06','FIN','La déclaration d’indépendance finlandaise',1917,'Le 6 décembre 1917, le Parlement finlandais approuve la déclaration d’indépendance préparée par le Sénat. La Finlande se sépare ainsi de la Russie dans le contexte des révolutions de 1917.','https://finland.fi/life-society/main-outlines-of-finnish-history/','turn272search3','ThisisFINLAND — ministère finlandais des Affaires étrangères')
add('12-07','USA','L’attaque de Pearl Harbor',1941,'Le 7 décembre 1941, les forces japonaises attaquent la base américaine de Pearl Harbor, à Hawaï. Cet événement précipite l’entrée des États-Unis dans la Seconde Guerre mondiale.','https://www.nps.gov/wwii/learn/historyculture/pearl-harbor.htm','turn272search2','National Park Service')
add('12-08','BLR','L’accord fondateur de la Communauté des États indépendants',1991,'Le 8 décembre 1991, les dirigeants de la Biélorussie, de la Russie et de l’Ukraine signent l’accord créant la Communauté des États indépendants. Ce jalon accompagne la disparition de l’Union soviétique.','https://www.cvce.eu/recherche/unit-content/-/unit/en/02bb76df-d066-4c08-a58a-d4686a3e68ff/a36c2b08-97a1-4308-b764-6ad5988d939b/Resources','turn272search4','CVCE — université du Luxembourg')
add('12-09','TZA','L’indépendance du Tanganyika',1961,'Le Tanganyika devient indépendant le 9 décembre 1961. Il s’unira à Zanzibar en 1964 pour former la Tanzanie ; les deux événements ne doivent pas être confondus.','https://www.ch.tzembassy.go.tz/multilateralism','turn285search4','Mission de Tanzanie auprès des Nations unies à Genève')
add('12-10','FRA','La Déclaration universelle des droits de l’homme est adoptée à Paris',1948,'Le 10 décembre 1948, l’Assemblée générale des Nations unies adopte à Paris la Déclaration universelle des droits de l’homme. Ce texte international énonce des droits destinés à toutes les personnes.','https://www.un.org/en/about-us/universal-declaration-of-human-rights','turn273search1','Nations unies')
add('12-11','BFA','La proclamation de la République de Haute-Volta',1958,'Le 11 décembre 1958, la Haute-Volta devient une république au sein de la Communauté française. Ce changement précède l’indépendance de 1960 ; le nom Burkina Faso sera adopté en 1984.','https://fasoeducation.bf/espace_eleves/secondaire/general/terminale/terminale_a/histoire/decolonisation_burkina_faso/co/grainFormesdeLuttepourDecolonisation.html','turn276search2','Fasoéducation — ressources pédagogiques nationales')
add('12-12','KEN','L’indépendance du Kenya',1963,'Le Kenya devient indépendant le 12 décembre 1963. La fin de l’administration britannique constitue un jalon majeur de son histoire politique.','https://history.state.gov/countries/kenya','turn273search0','Office of the Historian')
add('12-13','POL','La loi martiale en Pologne',1981,'Le 13 décembre 1981, les autorités communistes imposent la loi martiale en Pologne. Cette mesure vise notamment le mouvement Solidarność et entraîne une forte répression politique.','https://eng.ipn.gov.pl/en/brief-history-of-poland/collected-content/9083%2CCOLLECTED-CONTENT-Martial-Law-in-Poland-19811983.html','turn274search6','Institut polonais de la mémoire nationale')
add('12-14','BIH','La signature des accords de paix pour la Bosnie-Herzégovine',1995,'Le 14 décembre 1995, les accords négociés à Dayton sont formellement signés à Paris. Ils définissent le cadre de paix et les institutions de la Bosnie-Herzégovine après la guerre.','https://nato.int/en/what-we-do/operations-and-missions/peace-support-operations-in-bosnia-and-herzegovina-1995-2004','turn274search1','OTAN — historique des opérations')
add('12-15','USA','La ratification du Bill of Rights',1791,'Le 15 décembre 1791, dix amendements à la Constitution américaine sont ratifiés et forment le Bill of Rights. Ils énoncent notamment des protections pour les libertés et les procédures judiciaires.','https://www.archives.gov/legislative/features/bor','turn274search13','National Archives')
add('12-16','KAZ','L’indépendance du Kazakhstan',1991,'Le Kazakhstan proclame son indépendance le 16 décembre 1991. Cette décision intervient dans les dernières semaines d’existence de l’Union soviétique.','https://www.gov.kz/uploads/2022/6/21/cd9b96fe6b95dc380c88dade8fae93d2_original.61045758.pdf','turn276search9','Gouvernement du Kazakhstan — présentation historique')
add('12-17','BTN','Le début de la monarchie héréditaire bhoutanaise',1907,'Le 17 décembre 1907, Ugyen Wangchuck devient le premier roi de la monarchie héréditaire du Bhoutan. Cette date fonde la fête nationale du pays.','https://www.mfa.gov.bt/wp-content/uploads/2022/12/window-on-Bhutan-2022.pdf','turn276search8','Ministère bhoutanais des Affaires étrangères')
add('12-18','NER','La proclamation de la République du Niger',1958,'Le 18 décembre 1958, le Niger prend le titre de république et devient un État membre de la Communauté française. L’indépendance complète interviendra le 3 août 1960.','https://mjp.univ-perp.fr/constit/ne1960ind.htm','turn276search4','Université de Perpignan — texte de la délibération originale')
add('12-19','IND','La fin de l’administration portugaise de Goa',1961,'Le 19 décembre 1961, après l’intervention militaire indienne, Goa cesse d’être administrée par le Portugal. Le territoire devient ensuite un État de l’Inde en 1987.','https://dcsgoa.dcourts.gov.in/about-department/history/','turn278search6','Tribunal du district de Goa du Sud')
add('12-20','MAC','Le transfert de Macao à la Chine',1999,'Le 20 décembre 1999, Macao passe de l’administration portugaise à celle de la Chine. Le territoire devient une région administrative spéciale.','https://bo.dsaj.gov.mo/bo/ii/2001/02/aviso02.asp','turn278search1','Bulletin officiel de Macao — notification diplomatique')
add('12-21','USA','Apollo 8 part vers la Lune',1968,'Apollo 8 décolle le 21 décembre 1968. Ses trois astronautes deviennent les premiers humains à quitter l’orbite terrestre pour effectuer un voyage autour de la Lune.','https://science.nasa.gov/resource/apollo-8-first-humans-to-leave-earth-orbit/','turn278search5','NASA')
add('12-22','ROU','La chute du régime Ceaușescu',1989,'Le 22 décembre 1989, Nicolae Ceaușescu fuit le siège du pouvoir à Bucarest. Ce tournant de la révolution roumaine met fin à son régime, sans mettre immédiatement fin aux violences.','https://amnr.defense.ro/webroot/fileslib/upload/files/Revista_Document/Revista_046_2009.pdf','turn285search51','Archives militaires nationales roumaines — revue Document')
add('12-23','JPN','L’achèvement de la tour de Tokyo',1958,'La tour de Tokyo est achevée le 23 décembre 1958. Cette tour de communication devient un repère architectural de la capitale japonaise et de sa reconstruction d’après-guerre.','https://gallery.tokyotower.co.jp/en/','turn280search2','Tokyo Tower — galerie historique officielle')
add('12-24','LBY','L’indépendance de la Libye',1951,'La Libye proclame son indépendance le 24 décembre 1951 sous la forme d’un royaume. L’ancien territoire colonial italien sort alors de l’administration exercée après la guerre par la France et le Royaume-Uni.','https://history.state.gov/countries/libya','turn284view2','Office of the Historian')
add('12-25','GBR','Le couronnement de Guillaume le Conquérant',1066,'Le 25 décembre 1066, Guillaume le Conquérant est couronné roi d’Angleterre à Westminster. Ce couronnement suit sa victoire à Hastings et inaugure une nouvelle dynastie.','https://www.londonmuseum.org.uk/collections/london-stories/how-norman-conquest-changed-london/','turn280search8','London Museum')
add('12-26','RUS','La dissolution formelle de l’Union soviétique',1991,'Le 26 décembre 1991, une déclaration du Soviet suprême constate la fin de l’Union soviétique. Elle intervient le lendemain de la démission de Mikhaïl Gorbatchev.','https://www.ebrd.com/content/dam/ebrd_dxp/assets/pdfs/communications-department/annual-review/annual-review-1991/annual-report-1991-english.pdf','turn283search9','Banque européenne pour la reconstruction et le développement — rapport de 1991')
add('12-27','IDN','Le transfert de souveraineté à l’Indonésie',1949,'Le 27 décembre 1949, les Pays-Bas transfèrent la souveraineté aux États-Unis d’Indonésie. Ce jalon est distinct de la proclamation indonésienne d’indépendance du 17 août 1945.','https://www.nationaalarchief.nl/beleven/nieuws/herdenking-15-augustus','turn282search5','Archives nationales des Pays-Bas')
add('12-28','FRA','Une séance fondatrice du Cinématographe Lumière',1895,'Le 28 décembre 1895, les frères Lumière organisent une séance publique payante de leur Cinématographe au Grand Café à Paris. Cet événement devient un repère de l’histoire du cinéma.','https://www.institut-lumiere.org/index.php/musee-lumiere-fr','turn282search2','Institut Lumière')
add('12-29','MNG','Le couronnement du Bogd Khan',1911,'Le 29 décembre 1911, le Bogd Khan est intronisé en Mongolie. Cet événement accompagne la proclamation de l’indépendance mongole vis-à-vis de la dynastie Qing.','https://www.khm.uio.no/english/collections/mongolia/','turn282search3','Musée d’histoire culturelle — université d’Oslo')
add('12-30','PHL','L’exécution de José Rizal',1896,'L’écrivain et médecin José Rizal est exécuté le 30 décembre 1896 à Manille. Ses écrits contre les injustices coloniales et sa mort occupent une place majeure dans l’histoire nationale philippine.','https://rizal.nationalmuseum.gov.ph/essays/rizal-as-hero/','turn283search2','Musée national des Philippines')
add('12-31','PAN','Le Panama prend le contrôle du canal',1999,'Le 31 décembre 1999 à midi, le contrôle et l’exploitation du canal sont transférés au Panama. Ce transfert achève le processus prévu par les traités de 1977.','https://1997-2001.state.gov/regions/wha/panama/991206_faqs.html','turn283search6','Département d’État — documentation du transfert')
for r in rows:
 if r['date']=='10-09':r.update(url='https://paris.mofa.go.ug/basic-page/history-and-politics',source_title='Ambassade de l’Ouganda en France',evidence='Date complète d’indépendance confirmée : turn285search0')
 if r['date']=='11-25':r.update(url='https://history.state.gov/countries/suriname',source_title='Office of the Historian',evidence='Cérémonie de proclamation explicitement datée : turn284view3')
rows.sort(key=lambda r:r['date'])
p.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
Path('editorial15/calendar_q4_missing.json').write_text('[]\n')
dates=[(datetime.date(2024,10,1)+datetime.timedelta(days=i)).strftime('%m-%d') for i in range(92)]
countries=json.load(open('v14_work/Meridien/data/countries.json'))
assert len(rows)==92 and len({r['date'] for r in rows})==92
assert set(dates)=={r['date'] for r in rows}
assert all(r['code'] in countries for r in rows)
print('92 dates, 92 sources, 0 missing; ISO3 codes validated')
